\title{Kernel Patterns: Complete Invariants of Tuples under Alphabet
Permutations, and the Bell--Stirling Calculus They Generate}
\author{Aristotle}
\date{19 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For a tuple $x=(x_1,\dots,x_n)$ with entries in a set $\alpha$, its \emph{kernel}
(equality pattern) is the equivalence relation $i \sim_x j \iff x_i = x_j$ on the index
set. We develop a complete theory of this invariant for the natural action of the
symmetric group $\Sym(\alpha)$ on $\alpha^n$ by relabelling of entries. We introduce a
computable canonical form $\can(x)_i = \min\{j : x_j = x_i\}$, characterise its image as
the set of \emph{idempotent contracting retractions} of $\{0,\dots,n-1\}$ (the restricted
growth encodings of set partitions), and prove that the kernel is both invariant and
complete: two tuples over the same alphabet---finite or infinite, with no cardinality
hypotheses---have the same kernel if and only if they lie in a common $\Sym(\alpha)$-orbit.
We then establish that the resulting set of patterns is canonically isomorphic to the set
of equivalence relations on an $n$-element set, whence its cardinality is the Bell number
$B_n$; as a by-product we obtain a self-contained proof that the binomial-recurrence Bell
numbers count set partitions, with the first six values $1,1,2,5,15,52$
(OEIS A000110) obtained by exhaustive enumeration of the finite set of patterns.
Refining by the number of blocks yields the Stirling numbers of the second kind $S(n,k)$
together with $\sum_k S(n,k) = B_n$; realisability over an alphabet of size $a$ yields a
truncated Stirling row $\sum_{k \le a} S(n,k)$ as the exact orbit count for \emph{every}
finite alphabet, with the closed forms $2^{n}$ (binary, length $n+1$) and $(3^{n}+1)/2$
(ternary, length $n+1$). Fibring the tuples over their patterns gives the connection
formula $a^n = \sum_k S(n,k)\,\ff{a}{k}$ between ordinary powers and falling factorials as a
pure counting identity. Finally, we compute the dimension of the space of
relabelling-invariant $K$-valued functions of an $n$-tuple: it equals $B_n$ whenever
$n \le |\alpha|$.
\end{abstract}

\section{Introduction}

Let $\alpha$ be a set (the \emph{alphabet}) and let $n \ge 0$. The symmetric group
$\Sym(\alpha)$ of all bijections $\alpha \to \alpha$ acts on the set $\alpha^n$ of
$n$-tuples by postcomposition,
\[
  \sigma \cdot (x_1,\dots,x_n) = (\sigma x_1,\dots,\sigma x_n),
\]
formalising the idea of \emph{renaming the letters}. Two questions arise: which features
of a tuple survive renaming, and how many orbits are there? The answer to the first is a
single feature---the pattern of coincidences among the entries---and the answer to the
second is the Bell number, with a precise correction when the alphabet is too small to
realise every pattern. This paper develops both answers in full, deriving the
intermediate combinatorics (Bell recurrence, Stirling recurrence, power/falling-factorial
connection formula) from the classification rather than assuming it.

Throughout, indices run over $[n] := \{0,1,\dots,n-1\}$ with its usual linear order.

\section{The kernel, its canonical form, and patterns}

\begin{definition}[Kernel]
For $x \in \alpha^n$, the \emph{kernel} of $x$ is the equivalence relation $\ker x$ on
$[n]$ given by $i \mathrel{(\ker x)} j \iff x_i = x_j$. Reflexivity, symmetry and
transitivity are inherited from equality.
\end{definition}

\begin{definition}[Same kernel]
For $x \in \alpha^n$ and $y \in \beta^n$ (possibly over different alphabets) write
\[
  \SameKer(x,y) \iff \bigl(\forall i,j \in [n]:\ x_i = x_j \leftrightarrow y_i = y_j\bigr).
\]
\end{definition}

\begin{lemma}
$\SameKer$ is reflexive, symmetric and transitive across alphabets, and
$\SameKer(x,y) \iff \ker x = \ker y$.
\end{lemma}

\begin{proof}
Immediate from the definitions; the second claim is extensionality of relations.
\end{proof}

\begin{definition}[Canonical form]
For $x \in \alpha^n$ define $\can(x): [n] \to [n]$ by
$\can(x)_i = \min\{\, j \in [n] : x_j = x_i \,\}$. The set is nonempty (it contains $i$)
and finite, so the minimum exists.
\end{definition}

\begin{lemma}[Basic properties]\label{lem:basic}
For all $i,j$:
\begin{enumerate}
  \item $x_{\can(x)_i} = x_i$;
  \item $\can(x)_i \le i$, and more generally $x_j = x_i \Rightarrow \can(x)_i \le j$;
  \item $\can(x)_i = \can(x)_j \iff x_i = x_j$;
  \item $\can(x)_{\can(x)_i} = \can(x)_i$.
\end{enumerate}
\end{lemma}

\begin{proof}
(1) and (2) are the defining properties of the minimum of $\{j : x_j = x_i\}$. For (3): if
the canonical indices agree then $x_i = x_{\can(x)_i} = x_{\can(x)_j} = x_j$ by (1);
conversely $x_i = x_j$ makes the two defining sets literally equal, hence their minima
equal. Item (4) is (3) applied to (1).
\end{proof}

\begin{proposition}[Completeness of the encoding]\label{prop:enc}
For $x \in \alpha^n$, $y \in \beta^n$: $\SameKer(x,y) \iff \can(x) = \can(y)$.
\end{proposition}

\begin{proof}
($\Rightarrow$) Same kernel makes $\{j : x_j = x_i\}$ and $\{j : y_j = y_i\}$ equal for
each $i$; take minima. ($\Leftarrow$) By Lemma~\ref{lem:basic}(3),
$x_i = x_j \iff \can(x)_i = \can(x)_j = \can(y)_i = \can(y)_j \iff y_i = y_j$.
\end{proof}

\begin{theorem}[Invariance under injective relabelling]\label{thm:inv}
Let $f : \alpha \to \beta$ be injective. Then $\can(f \circ x) = \can(x)$ for all
$x \in \alpha^n$; in particular $\SameKer(f \circ x, x)$.
\end{theorem}

\begin{proof}
Injectivity gives $f(x_j) = f(x_i) \iff x_j = x_i$, so the two defining sets coincide for
each $i$; take minima.
\end{proof}

In particular the kernel is a $\Sym(\alpha)$-invariant. Theorem~\ref{thm:inv} is strictly
stronger: stability under arbitrary injections, including injections between different
alphabets, makes canonical forms comparable across alphabets.

\begin{theorem}[Completeness, finite alphabet]\label{thm:compfin}
Let $\alpha$ be finite and $x,y \in \alpha^n$. Then
$\SameKer(x,y) \iff \exists \sigma \in \Sym(\alpha):\ \sigma \circ x = y$.
\end{theorem}

\begin{proof}
($\Leftarrow$) is Theorem~\ref{thm:inv}. ($\Rightarrow$) Let $S = \{x_i\}$ and
$T = \{y_i\}$ be the value sets. For $a \in S$ pick $\iota(a)$ with $x_{\iota(a)} = a$ and
define $f : S \to T$, $f(a) = y_{\iota(a)}$. If $f(a) = f(b)$ then
$y_{\iota(a)} = y_{\iota(b)}$, so same kernel gives $x_{\iota(a)} = x_{\iota(b)}$, i.e.
$a=b$: $f$ is injective (and in particular well defined). Given $b = y_i \in T$, put
$a = x_i$; then $x_{\iota(a)} = x_i$, so $y_{\iota(a)} = y_i = b$: $f$ is surjective. Thus
$f$ is a bijection between subsets of the finite set $\alpha$ of equal cardinality, so
their complements have equal cardinality and $f$ extends to $\sigma \in \Sym(\alpha)$. For
each $i$, taking $a = x_i$ gives $\sigma(x_i) = f(x_i) = y_{\iota(x_i)} = y_i$.
\end{proof}

\begin{definition}[Pattern]
A map $p : [n] \to [n]$ is a \emph{pattern} if for every $i$,
\[
  p(i) \le i \quad \text{(contracting)} \qquad\text{and}\qquad p(p(i)) = p(i)
  \quad \text{(idempotent)}.
\]
Write $\mathcal{P}_n$ for the set of patterns on $n$ letters. Both conditions are
decidable, so $\mathcal{P}_n$ is an explicitly enumerable finite set. Patterns are exactly
the \emph{restricted growth encodings} of set partitions of $[n]$: $p(i)$ names the block
of $i$ by its least element.
\end{definition}

\begin{theorem}[Retraction]\label{thm:retract}
$\can$ maps $\alpha^n$ onto $\mathcal{P}_n$, and $\can(p) = p$ for every
$p \in \mathcal{P}_n$. Hence $\can$ is an idempotent retraction of tuples onto patterns,
and $\mathcal{P}_n$ is a complete, irredundant set of normal forms for the kernel.
\end{theorem}

\begin{proof}
That $\can(x)$ is a pattern is Lemma~\ref{lem:basic}(2),(4). Let $p$ be a pattern and
$i \in [n]$. Since $p(p(i)) = p(i)$, the index $p(i)$ lies in $\{j : p(j) = p(i)\}$, so
$\can(p)_i \le p(i)$. Conversely $p(\can(p)_i) = p(i)$ by Lemma~\ref{lem:basic}(1) and $p$
is contracting, so $p(i) = p(\can(p)_i) \le \can(p)_i$. Antisymmetry gives equality;
surjectivity follows.
\end{proof}

\begin{definition}
For $x \in \alpha^n$ write $\pat(x) := \can(x) \in \mathcal{P}_n$.
\end{definition}

\begin{corollary}\label{cor:orbitinv}
For finite $\alpha$ and $x,y \in \alpha^n$: $\pat(x) = \pat(y)$ if and only if $x$ and $y$
lie in the same $\Sym(\alpha)$-orbit.
\end{corollary}

\section{Counting: patterns are equivalence relations}

\begin{definition}
The Bell numbers are defined by $B_0 = 1$ and
$B_{n+1} = \sum_{k=0}^{n}\binom{n}{k} B_{n-k}$.
\end{definition}

Write $E(m)$ for the number of equivalence relations on an $m$-element set; this is well
defined since any bijection of underlying sets transports equivalence relations
bijectively.

\begin{definition}
For an equivalence relation $s$ on $\beta \sqcup \{\ast\}$, let
$\blk(s) = \{b \in \beta : b \mathrel{s} \ast\}$.
\end{definition}

\begin{definition}[Gluing]
Given $S \subseteq \beta$ and an equivalence relation $t$ on $\beta \setminus S$, define
$R(S,t)$ on $\beta \sqcup \{\ast\}$ by: $\ast \mathrel{R} \ast$;
$\ast \mathrel{R} b \iff b \in S$; $a \mathrel{R} \ast \iff a \in S$; and for
$a,b \in \beta$,
\[
  a \mathrel{R} b \iff
  \begin{cases}
    b \in S, & a \in S,\\
    \text{false}, & a \notin S,\ b \in S,\\
    a \mathrel{t} b, & a,b \notin S.
  \end{cases}
\]
\end{definition}

\begin{lemma}[Fibre description]\label{lem:fibre}
$R(S,t)$ is an equivalence relation with $\blk(R(S,t)) = S$, and the assignments
$t \mapsto R(S,t)$ and $s \mapsto s|_{\beta \setminus S}$ are mutually inverse bijections
between $\{s : \blk(s) = S\}$ and the equivalence relations on $\beta \setminus S$.
\end{lemma}

\begin{proof}[Proof sketch]
Reflexivity, symmetry and transitivity of $R(S,t)$ are checked case-by-case on whether
each argument is $\ast$, in $S$, or outside $S$; the only nontrivial cases are transitivity
chains crossing the boundary of $S$, which are handled by the fact that $R$ never relates a
point of $S$ to a point outside $S$. That $\blk(R(S,t)) = S$ is immediate. Starting from
$s$ with $\blk(s) = S$ one shows $s = R(S, s|_{\beta\setminus S})$ by the same case
analysis, using $b \in S \iff b \mathrel{s} \ast$ and transitivity of $s$; conversely
$R(S,t)$ restricted to $\beta \setminus S$ is $t$ by definition.
\end{proof}

\begin{theorem}[Bell numbers count equivalence relations]\label{thm:bellcount}
$E(n) = B_n$ for all $n$.
\end{theorem}

\begin{proof}
Summing Lemma~\ref{lem:fibre} over the fibres of $\blk$ for $|\beta| = m$ gives
$E(m+1) = \sum_{S \subseteq \beta} E(m - |S|) = \sum_{k=0}^{m}\binom{m}{k} E(m-k)$, after
grouping subsets by size. Also $E(0) = 1$. This is the defining recurrence, and strong
induction concludes.
\end{proof}

\begin{theorem}[Classification of patterns]\label{thm:classify}
The maps $p \mapsto \ker p$ and $s \mapsto \can\bigl(i \mapsto [i]_s\bigr)$ are mutually
inverse bijections between $\mathcal{P}_n$ and the set of equivalence relations on $[n]$,
where $[i]_s$ is the $s$-class of $i$.
\end{theorem}

\begin{proof}
The quotient tuple $q_s : i \mapsto [i]_s$ has $\ker q_s = s$. Also $\ker \can(x) = \ker x$
for any $x$, by Lemma~\ref{lem:basic}(3); hence $\ker(\can(q_s)) = s$. Conversely, for a
pattern $p$ we have $\SameKer(q_{\ker p}, p)$, so $\can(q_{\ker p}) = \can(p) = p$ by
Proposition~\ref{prop:enc} and Theorem~\ref{thm:retract}.
\end{proof}

\begin{theorem}[Pattern count]\label{thm:patcount}
$|\mathcal{P}_n| = B_n$.
\end{theorem}

\begin{proof}
Combine Theorems~\ref{thm:classify} and \ref{thm:bellcount}.
\end{proof}

\begin{theorem}[Small values]
$|\mathcal{P}_0|,\dots,|\mathcal{P}_5| = 1,1,2,5,15,52$, hence
$(B_0,\dots,B_5) = (1,1,2,5,15,52)$ (OEIS A000110).
\end{theorem}

\begin{proof}
$\mathcal{P}_n$ is a decidable subset of the finite set $[n]^{[n]}$, so its cardinality is
obtained by exhaustive enumeration; transport along Theorem~\ref{thm:patcount}.
\end{proof}

\begin{theorem}[Orbit count for a large alphabet]\label{thm:orbitbell}
Let $\alpha$ be finite with $n \le |\alpha|$. Then $\Sym(\alpha)$ has exactly $B_n$ orbits
on $\alpha^n$, the orbit invariant being $\pat$.
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:orbitinv}, $\pat$ descends to an injection of the orbit space into
$\mathcal{P}_n$. Given $p \in \mathcal{P}_n$, choose an injection $f : [n] \hookrightarrow
\alpha$; then $\pat(f \circ p) = \can(p) = p$ by Theorems~\ref{thm:inv} and
\ref{thm:retract}. Now apply Theorem~\ref{thm:patcount}.
\end{proof}

\begin{example}
$\Sym(\{1,\dots,5\})$ has exactly $52$ orbits on the $3125$ quintuples over a five-letter
alphabet.
\end{example}

\section{The block-refined count: Stirling numbers of the second kind}

\begin{definition}
For $p \in \mathcal{P}_n$ let $\blocks(p) = |p([n])|$. By idempotence this is the number of
fixed points of $p$, and also the number of classes of $\ker p$.
\end{definition}

\begin{lemma}\label{lem:blockcount}
For $x \in \alpha^n$, $\blocks(\pat(x)) = |\{x_i : i \in [n]\}|$.
\end{lemma}

\begin{proof}
The map $j \mapsto x_j$ restricts to a bijection from the image of $\can(x)$ (a set of
fixed points) onto the value set of $x$: injective by Lemma~\ref{lem:basic}(3) together
with fixedness, surjective since $x_{\can(x)_i} = x_i$.
\end{proof}

\begin{definition}[Stirling numbers of the second kind]
$S(0,0) = 1$, $S(0,k+1) = 0$, $S(n+1,0) = 0$, and
$S(n+1,k+1) = (k+1)S(n,k+1) + S(n,k)$.
\end{definition}

\begin{theorem}[Block-refined count]\label{thm:stirling}
The number of patterns on $n$ letters with exactly $k$ blocks equals $S(n,k)$.
\end{theorem}

\begin{proof}
Let $N(n,k)$ be that number. Deleting the last coordinate of $p \in \mathcal{P}_{n+1}$
gives a well-defined $\rho(p) \in \mathcal{P}_n$ (contraction keeps the values in range,
idempotence is preserved). Conversely an extension of $q \in \mathcal{P}_n$ is determined
by the value $v$ at the new coordinate, and $v$ is admissible exactly when either $v$ is a
fixed point of $q$ (joining an existing block, block count unchanged) or $v$ is the new
coordinate itself (creating a new block, block count $+1$). Hence the fibre of $\rho$ over
$q$ inside the patterns with $k+1$ blocks has size $k+1$ if $\blocks(q) = k+1$, size $1$ if
$\blocks(q) = k$, and $0$ otherwise, so
$N(n+1,k+1) = (k+1)N(n,k+1) + N(n,k)$. The base cases match: $N(0,0) = 1$,
$N(0,k+1) = 0$, and $N(n+1,0) = 0$ because a nonempty pattern has at least one block.
\end{proof}

\begin{corollary}\label{cor:sumstirling}
$\sum_{k=0}^{n} S(n,k) = B_n$.
\end{corollary}

\begin{proof}
Partition $\mathcal{P}_n$ by block count (at most $n$) and apply
Theorems~\ref{thm:stirling} and \ref{thm:patcount}.
\end{proof}

\begin{example}
Row $n=4$ is $(0,1,7,6,1)$, summing to $15 = B_4$; row $n=5$ is $(0,1,15,25,10,1)$,
summing to $52 = B_5$.
\end{example}

\section{Small alphabets: realisability and truncated Stirling rows}

\begin{lemma}\label{lem:blocksle}
For finite $\alpha$ and $x \in \alpha^n$, $\blocks(\pat(x)) \le |\alpha|$.
\end{lemma}

\begin{proof}
By Lemma~\ref{lem:blockcount} the block count is the number of distinct entries.
\end{proof}

\begin{theorem}[Realisability]\label{thm:realise}
Let $\alpha$ be finite and $p \in \mathcal{P}_n$. Then $p = \pat(x)$ for some
$x \in \alpha^n$ if and only if $\blocks(p) \le |\alpha|$.
\end{theorem}

\begin{proof}
Necessity is Lemma~\ref{lem:blocksle}. For sufficiency choose an injection $e$ of the image
$p([n])$ into $\alpha$ and set $x_i = e(p(i))$; then $\SameKer(x,p)$ because $e$ is
injective, so $\pat(x) = \can(p) = p$.
\end{proof}

\begin{theorem}[Classification over an arbitrary finite alphabet]
For every finite alphabet $\alpha$ and every $n$, $\pat$ induces a bijection
\[
  \alpha^n/\Sym(\alpha) \;\xrightarrow{\ \sim\ }\;
  \{\, p \in \mathcal{P}_n : \blocks(p) \le |\alpha| \,\}.
\]
\end{theorem}

\begin{proof}
Injectivity is Corollary~\ref{cor:orbitinv}, well-definedness is
Lemma~\ref{lem:blocksle}, surjectivity is Theorem~\ref{thm:realise}.
\end{proof}

\begin{theorem}[Truncated Stirling row]\label{thm:trunc}
For every finite alphabet $\alpha$ with $|\alpha| = a$,
\[
  \bigl|\alpha^n/\Sym(\alpha)\bigr| \;=\; \sum_{k=0}^{a} S(n,k).
\]
\end{theorem}

\begin{proof}
Combine the previous theorem with Theorem~\ref{thm:stirling}, grouping by exact block
count.
\end{proof}

\begin{lemma}\label{lem:rows}
$S(m+1,1) = 1$, and $S(m+2,2) + 1 = 2^{m+1}$ (i.e.\ $S(m,2) = 2^{m-1}-1$ for $m \ge 2$).
\end{lemma}

\begin{proof}
Induction from the recurrence: $S(m+2,1) = S(m+1,1) + S(m+1,0) = 1$; and
$S(m+2,2)+1 = 2\bigl(S(m+1,2)+1\bigr)$, doubling from the base value $2$. The additive
phrasing avoids truncated subtraction.
\end{proof}

\begin{theorem}[Binary alphabet]\label{thm:binary}
For every $n$, the $(n+1)$-tuples over a two-letter alphabet fall into exactly $2^{n}$
orbits under the letter-swapping group.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:trunc} the count is $S(n+1,0)+S(n+1,1)+S(n+1,2) = 0 + 1 + (2^{n}-1)$
for $n \ge 1$ using Lemma~\ref{lem:rows}; $n = 0$ is a direct check.
\end{proof}

\begin{theorem}[Strictness]
For $n \ge 3$ the binary orbit count is strictly smaller than $B_n$.
\end{theorem}

\begin{proof}
The difference is $\sum_{k \ge 3} S(n,k) > 0$ because $S(n,3) > 0$ for $n \ge 3$
(induction: $S(3,3) = 1$ and $S(n+1,3) \ge S(n,3)$). At $n = 3$ the count is $4$ versus
$B_3 = 5$; the unattainable pattern has three singleton blocks.
\end{proof}

\begin{theorem}[Ternary alphabet]
For every $n$, the $(n+1)$-tuples over a three-letter alphabet fall into $N$ orbits with
$2N = 3^{n}+1$, i.e.\ $N = (3^{n}+1)/2$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:trunc}, $N = \sum_{k \le 3} S(n+1,k)$, and
$2\sum_{k \le 3} S(m+1,k) = 3^{m}+1$ follows by induction on $m$ from the Stirling
recurrence, the base case being $2\cdot 1 = 1+1$. The integral formulation avoids
division.
\end{proof}

\section{Arbitrary alphabets, the connection formula, and invariant functions}

\begin{theorem}[Completeness, general alphabet]\label{thm:compgen}
For an arbitrary set $\alpha$ and $x,y \in \alpha^n$,
$\SameKer(x,y) \iff \exists \sigma \in \Sym(\alpha):\ \sigma \circ x = y$.
\end{theorem}

\begin{proof}
The finite case is Theorem~\ref{thm:compfin}. If $\alpha$ is infinite, construct the
bijection $f : S \to T$ between the finite value sets exactly as there. To extend $f$ one
needs a bijection $\alpha \setminus S \to \alpha \setminus T$; since $S,T$ are finite and
$\alpha$ is infinite, both complements have cardinality $|\alpha|$, so such a bijection
exists. Gluing gives $\sigma$, and $\sigma(x_i) = y_i$ follows as before.
\end{proof}

\begin{example}
Over $\mathbb{N}$, the tuples $(0,0,1)$ and $(5,5,7)$ have the same kernel, so some
permutation $\sigma$ of $\mathbb{N}$ satisfies $\sigma \circ (0,0,1) = (5,5,7)$.
\end{example}

Fix a finite alphabet of size $a$ and write $\ff{a}{k} = a(a-1)\cdots(a-k+1)$, with
$\ff{a}{k} = 0$ for $k > a$.

\begin{theorem}[Fibre size]\label{thm:fibresize}
For $p \in \mathcal{P}_n$ with $k = \blocks(p)$,
$\bigl|\{x \in \alpha^n : \pat(x) = p\}\bigr| = \ff{a}{k}$.
\end{theorem}

\begin{proof}
A tuple $x$ with $\pat(x) = p$ is exactly an \emph{injective} labelling of the blocks of
$p$ by letters: given $x$, the assignment sending a block to the common value of $x$ on it
is injective (otherwise two blocks would merge, changing the pattern); conversely any
injection $\varphi$ from the $k$-element block set into $\alpha$ yields
$x_i = \varphi(\text{block of } i)$ with $\pat(x) = \can(p) = p$ by
Theorems~\ref{thm:inv} and \ref{thm:retract}. These assignments are mutually inverse, and
the number of injections from a $k$-set into an $a$-set is $\ff{a}{k}$.
\end{proof}

\begin{theorem}[Connection formula]\label{thm:connection}
For all $a,n \ge 0$,
\[
  a^{n} \;=\; \sum_{k=0}^{n} S(n,k)\, \ff{a}{k}.
\]
\end{theorem}

\begin{proof}
Count $\alpha^n$ (of size $a^n$) by fibring over $\pat$ and grouping patterns by block
count: each pattern with $k$ blocks contributes $\ff{a}{k}$ by
Theorem~\ref{thm:fibresize}, and there are $S(n,k)$ of them by Theorem~\ref{thm:stirling}.
\end{proof}

\begin{remark}
Theorem~\ref{thm:connection} explains the truncation of Theorem~\ref{thm:trunc}: the terms
with $k > a$ vanish because $\ff{a}{k} = 0$---exactly the patterns declared unrealisable by
Theorem~\ref{thm:realise}. Numerically, at $a=3$, $n=4$:
$81 = 0\cdot 1 + 1\cdot 3 + 7\cdot 6 + 6\cdot 6 + 1\cdot 0$.
\end{remark}

Let $K$ be a field and $\beta$ a finite alphabet, and set
\[
  \Inv_K(\beta,n) = \bigl\{ f : \beta^n \to K \ \bigm|\ f(\sigma \circ x) = f(x)
  \ \ \forall \sigma \in \Sym(\beta),\ \forall x \bigr\},
\]
a $K$-subspace of the space of all functions $\beta^n \to K$.

\begin{theorem}[Dimension of the invariants]
If $n \le |\beta| < \infty$ then $\dim_K \Inv_K(\beta,n) = B_n$.
\end{theorem}

\begin{proof}
Restriction along the quotient map $\beta^n \to \beta^n/\Sym(\beta)$ is a $K$-linear
isomorphism from the space of all functions on the finite orbit space onto
$\Inv_K(\beta,n)$: an invariant function is constant on orbits and factors uniquely through
the quotient, and every function on the quotient pulls back to an invariant function. The
space of $K$-valued functions on a finite set of size $m$ has dimension $m$, and the orbit
space has size $B_n$ by Theorem~\ref{thm:orbitbell}.
\end{proof}

A relabelling-invariant function of $n$ arguments drawn from a sufficiently large alphabet
is therefore \emph{precisely} a function of the equality pattern, with exactly $B_n$
degrees of freedom---$52$ for $n = 5$, however large the alphabet. Over a small alphabet
the dimension drops to $\sum_{k \le |\beta|} S(n,k)$ by the same argument together with
Theorem~\ref{thm:trunc}.

\section{Algorithms}

Let $n$ be the tuple length and $a$ the alphabet size.

\paragraph{Canonical form.} A single left-to-right pass with a dictionary from value to
first index computes $\can(x)$ in $O(n)$ expected time: for $i = 0,\dots,n-1$, if $x_i$ is
unseen record $\mathrm{first}[x_i] \leftarrow i$, and output $\can(x)_i =
\mathrm{first}[x_i]$. Correctness is immediate from the pass order. By
Proposition~\ref{prop:enc} and Theorem~\ref{thm:compgen} this gives an $O(n)$ test for
``are these two tuples renamings of one another?''.

\paragraph{Enumerating patterns.} The last-letter recursion of Theorem~\ref{thm:stirling}
generates each of the $B_n$ patterns exactly once with no rejection: extend a pattern $q$
on $n$ letters by choosing the last value among the fixed points of $q$ or the new index
itself. The cost is $O(n B_n)$, optimal up to the factor $n$ needed to write each pattern
down. Brute-force filtering of all $n^n$ maps by the two pattern conditions also works and
is what makes small values verifiable by exhaustive search, but is exponentially wasteful.

\paragraph{Counting.} Bell and Stirling numbers are computed by dynamic programming in
$O(n^2)$ arithmetic operations, and the orbit count over an $a$-letter alphabet is the
prefix sum $\sum_{k \le a} S(n,k)$. For $a \in \{2,3\}$ the closed forms $2^{n-1}$ and
$(3^{n-1}+1)/2$ replace the sum.

\section{Applications}

\paragraph{Alpha-equivalence and name independence.} The doctrine that names of atoms do
not matter is exactly the statement that the content of a tuple of names is its kernel.
Theorem~\ref{thm:compgen} says this loses nothing: two name-tuples are interchangeable if
and only if their coincidence patterns agree. Canonical forms play the role of de Bruijn
indices.

\paragraph{Queries over an active domain.} A query whose answer must be equivariant under
renaming of constants can only depend on the pattern; Theorem~\ref{thm:trunc} counts the
distinguishable $n$-tuples over a domain of $a$ constants, and
Theorem~\ref{thm:fibresize} counts how many concrete tuples realise each.

\paragraph{Permutation-equivariant learning.} Models consuming a list of tokens and
required to be invariant under relabelling of the vocabulary can express exactly $B_n$
independent scalar features of an $n$-token input---an expressivity ceiling independent of
vocabulary size, dropping to $\sum_{k \le a} S(n,k)$ for small vocabularies.

\paragraph{Hash collision structure.} The pattern of a list of hash values is its collision
structure; over a codomain of size $a$, exactly $\ff{a}{k}$ assignments realise a fixed
structure with $k$ distinct values, and summing recovers $a^n$.

\paragraph{A classical identity by counting.} The change of basis
$x^n = \sum_k S(n,k)\, \ff{x}{k}$ between the monomial and falling-factorial bases is
usually proved by induction or generating functions; Theorem~\ref{thm:connection} derives
it for every nonnegative integer, hence---two polynomials agreeing at infinitely many
points being equal---as a polynomial identity.

\section{Discussion and future directions}

\paragraph{A Dobi\'nski-type analytic bridge.} Dobi\'nski's formula states
$B_n = e^{-1}\sum_{k \ge 0} k^n/k!$. The combinatorial engine is already present: the
connection formula $k^n = \sum_j S(n,j)\ff{k}{j}$ holds for each $k$, and summing against
the Poisson weights $e^{-1}/k!$ turns each term $\sum_k e^{-1}\ff{k}{j}/k!$ into $1$,
leaving $\sum_j S(n,j) = B_n$ by Corollary~\ref{cor:sumstirling}. The only missing
ingredient is the analytic justification of the exchange of summations.

\paragraph{The pattern poset is the partition lattice.} Order $\mathcal{P}_n$ by
refinement: $p \le q$ iff $p(i) = p(j) \Rightarrow q(i) = q(j)$. Conjecturally
Theorem~\ref{thm:classify} upgrades to an order isomorphism onto the lattice of
equivalence relations on $[n]$; then $\mathcal{P}_n$ is a complete lattice, is
non-distributive for $n \ge 3$, and has M\"obius function
$\mu(\hat0,\hat1) = (-1)^{n-1}(n-1)!$. The route is that $\can$ is a monotone retraction:
$\can(x)$ depends only on $\ker x$, so the refinement order on tuples descends to
patterns. The payoff is a computable, exhaustively enumerable encoding of the partition
lattice for incidence-algebra computations.

\paragraph{Kernels as complete invariants for injections.} Theorem~\ref{thm:inv} shows
invariance under arbitrary injective relabelling, including between different alphabets,
whereas Theorems~\ref{thm:compfin} and \ref{thm:compgen} invert this only inside a single
alphabet. The natural generalisation: for arbitrary sets $\alpha,\beta$ and tuples
$x \in \alpha^n$, $y \in \beta^n$, $\SameKer(x,y)$ should hold if and only if there are a
set $\gamma$, a tuple $z \in \gamma^n$ and injections $f : \gamma \hookrightarrow \alpha$,
$g : \gamma \hookrightarrow \beta$ with $f \circ z = x$ and $g \circ z = y$; moreover the
universal such $z$ should be $\can(x)$ with $\gamma = [n]$. This would give $\can$ a
universal property rather than an ad-hoc definition.

\paragraph{Further avenues.} A $q$-analogue via patterns of tuples over a vector space
(replacing equality by linear dependence); the classification for the action of
$\Sym(\alpha)\times\Sym([n])$, whose invariant is the multiset of block sizes and whose
count is the partition number $p(n)$; and asymptotics of the truncated rows
$\sum_{k \le a} S(n,k)$, which for fixed $a$ grow like $a^n/a!$.

\section{Summary of principal results}

\begin{center}
\begin{tabular}{ll}
\toprule
Statement & Content \\
\midrule
Invariance & $\can(f \circ x) = \can(x)$ for every injection $f$ \\
Completeness & Over any alphabet: same kernel $\iff$ same permutation orbit \\
Normal forms & Kernels $\leftrightarrow$ idempotent contracting retractions of $[n]$ \\
Classification & Patterns $\leftrightarrow$ equivalence relations on $[n]$ \\
Bell count & $|\mathcal{P}_n| = B_n$; first six values $1,1,2,5,15,52$ \\
Orbit count & $B_n$ orbits on $n$-tuples when $n \le |\alpha|$ \\
Stirling refinement & Patterns with $k$ blocks number $S(n,k)$; $\sum_k S(n,k) = B_n$ \\
Small alphabets & $\sum_{k \le |\alpha|} S(n,k)$; $2^{n}$ and $(3^{n}+1)/2$ for length $n+1$ \\
Connection formula & $a^n = \sum_k S(n,k)\,\ff{a}{k}$ \\
Invariant functions & $\dim_K \Inv_K(\beta,n) = B_n$ for $n \le |\beta|$ \\
\bottomrule
\end{tabular}
\end{center}

