"""Restricted-growth normalisation: the canonical form of the kernel of a tuple."""

from __future__ import annotations

from typing import Dict, Hashable, List, Sequence, Tuple


def canonical_form(x: Sequence[Hashable]) -> Tuple[int, ...]:
    """Return can(x) with can(x)_i = min { j : x_j = x_i }.

    One left-to-right pass with a dictionary from value to first occurrence.
    Time O(n) expected, space O(n).  The output is always a *pattern*: it is
    contracting (can(x)_i <= i) and idempotent (can(x) applied twice is itself).
    """
    first: Dict[Hashable, int] = {}
    out: List[int] = []
    for i, xi in enumerate(x):
        if xi not in first:
            first[xi] = i
        out.append(first[xi])
    return tuple(out)


def is_pattern(p: Sequence[int]) -> bool:
    """Test the two defining conditions of a pattern in O(n)."""
    return all(p[i] <= i and p[p[i]] == p[i] for i in range(len(p)))


def same_kernel(x: Sequence[Hashable], y: Sequence[Hashable]) -> bool:
    """Decide whether x and y are relabellings of one another, in O(n).

    Justified by the completeness theorem: over any alphabet, two tuples have the
    same kernel iff some permutation of the alphabet carries one to the other, and
    same kernel is equivalent to equality of canonical forms.
    """
    return len(x) == len(y) and canonical_form(x) == canonical_form(y)


def recover_relabelling(x: Sequence[Hashable],
                        y: Sequence[Hashable]) -> Dict[Hashable, Hashable]:
    """Return the (partial) bijection on used letters witnessing y = sigma o x.

    Raises ValueError when the kernels differ.  The partial bijection extends to a
    full permutation of any ambient alphabet containing both value sets, because the
    complements have equal cardinality (finite case) or both have the cardinality of
    the alphabet (infinite case).
    """
    if not same_kernel(x, y):
        raise ValueError("tuples have different kernels; no relabelling exists")
    sigma: Dict[Hashable, Hashable] = {}
    for xi, yi in zip(x, y):
        sigma[xi] = yi
    return sigma


if __name__ == "__main__":
    print(canonical_form("BANANA"))                 # (0, 1, 2, 1, 2, 1)
    print(canonical_form("XYZYZY"))                 # (0, 1, 2, 1, 2, 1)
    print(same_kernel("BANANA", "XYZYZY"))          # True
    print(recover_relabelling("BANANA", "XYZYZY"))  # {'B': 'X', 'A': 'Y', 'N': 'Z'}
